 const [history,setHistory]=useState<History[]>([]),[result,setResult]=useState<Result|null>(null),[requestId,setRequestId]=useState(''),[requests,setRequests]=useState<StoredRequest[]>([]),[roster,setRoster]=useState<Caregiver[]>([]),[bookings,setBookings]=useState<Booking[]>([]),[selectedBooking,setSelectedBooking]=useState<Booking|null>(null);
 const [asstMessages,setAsstMessages]=useState<AssistantMessage[]>([]),[asstFacts,setAsstFacts]=useState<StructuredFacts>({patient_target:'unspecified',age_group:'unspecified',symptoms:[],duration:'unspecified',severity:'unspecified',warning_signs:{},existing_conditions:[],allergies_medications:[],family_history:[],uploaded_documents:[],care_preference:'unspecified',uncertainties:[]}),[asstStatus,setAsstStatus]=useState<AssistantStatus|null>(null),[asstInput,setAsstInput]=useState(''),[asstBusy,setAsstBusy]=useState(false),[asstUnderstoodOpen,setAsstUnderstoodOpen]=useState(true);
