 const [language,setLanguage]=useState<Lang>(()=>{const l=localStorage.getItem('tg-language');return l&&l in copy?l as Lang:'English';}),[large,setLarge]=useState(()=>localStorage.getItem('tg-large')==='true'),[reduce,setReduce]=useState(()=>localStorage.getItem('tg-motion')==='true'),[spoken,setSpoken]=useState(()=>localStorage.getItem('tg-spoken')==='true'),[review,setReview]=useState(false);
 const [examples,setExamples]=useState<Example[]>([]),[voiceStatus,setVoiceStatus]=useState(''),[listening,setListening]=useState(false),[provider,setProvider]=useState<Caregiver|null>(null),[slots,setSlots]=useState<Slot[]>([]),[chosen,setChosen]=useState<Slot|null>(null),[day,setDay]=useState(dayInIndia),[slotNote,setSlotNote]=useState(''),[filter,setFilter]=useState('all');
 const [consent,setConsent]=useState(false),[handovers,setHandovers]=useState<Handover[]>([]),[activeHandover,setActiveHandover]=useState<Handover|null>(null),[hospitals,setHospitals]=useState<Hospital[]>([]),[hospitalId,setHospitalId]=useState('aiims'),[lookup,setLookup]=useState<Lookup|null>(null),[tinyConfigured,setTinyConfigured]=useState(false),[metrics,setMetrics]=useState<Record<string,unknown>|null>(null);
 const recognition=useRef<Recognition|null>(null),idem=useRef(''),heading=useRef<HTMLHeadingElement>(null),inflight=useRef(false);const t=copy[language];
 const serviceNames:Record<string,string>={paramedic_home_visit:t.assessment,home_nursing:t.nursing,lab_test_home:t.lab,teleconsultation:t.video,emergency_112:'Emergency Help'};
 const services=[{id:'paramedic_home_visit',label:t.assessment,Icon:BriefcaseMedical,color:'coral'},{id:'home_nursing',label:t.nursing,Icon:Stethoscope,color:'blue'},{id:'lab_test_home',label:t.lab,Icon:TestTubes,color:'purple'},{id:'teleconsultation',label:t.video,Icon:Video,color:'green'}];
 useEffect(()=>{localStorage.setItem('tg-language',language);document.documentElement.lang=language==='Hindi'?'hi':'en';},[language]);
